// TypeScript types generated by hand from docs/design/data/data-model.json.
// Keep in sync with that file.

export type ISO = string;
export type Level = 'ok' | 'warn' | 'alert';
export type BodyArea = 'head' | 'torso' | 'armL' | 'armR' | 'legL' | 'legR';
export type Areas = Record<BodyArea, Level>;

export interface Environment {
  id: string;
  name: string;
  type: 'lab' | 'sleep' | 'gym' | 'galley' | 'node';
  areaM2: number;
}

export interface Mission {
  id: string;
  name: string;
  destination: 'LEO' | 'ISS' | 'Moon' | 'Mars';
  startDate: string;
  lengthDays: number;
  today: number;
  commDelaySec: number;
  goals: { exerciseMinPerDay: number; exerciseDaysPerWeek: number; sleepHours: number; kcalPerDay: number };
  environments: Environment[];
}

export type ShopCategory = 'helmet' | 'suit' | 'pet' | 'window' | 'wall' | 'floor';
export type AvatarState = 'idle' | 'walking' | 'happy' | 'tired' | 'sleepy' | 'sad';

export interface Equipped {
  helmet: string;
  suit: string;
  pet: string | null;
  room: { window: string; wall: string; floor: string };
}

export interface Astronaut {
  id: string;
  name: string;
  crewId: string;
  role: 'astronaut';
  profile: { age: number; heightCm: number; weightKg: number; foodPreferences: string[] };
  baseline: {
    boneDensity: number;
    muscleMassKg: number;
    strengthScore: number;
    aerobicScore: number;
    bodyFatPct: number;
    restingHr: number;
    restingBp: string;
    usualSleepH: number;
    usualBedtime: string;
  };
  devices: { wristBand: { model: string; paired: boolean }; dosimeterBadgeId: string; bpCuff: boolean };
  avatar: {
    name: string;
    level: number;
    coins: number;
    owned: string[];
    equipped: Equipped;
    state: AvatarState;
  };
  onboardingDone: boolean;
}

// ---- Logs ----
export type LogType = 'mood' | 'sleep' | 'radiation' | 'measurement' | 'injury' | 'meal' | 'exercise' | 'meditation';
export type MoodLabel = 'great' | 'good' | 'okay' | 'tired' | 'stressed';

export interface MoodData {
  level: 1 | 2 | 3 | 4 | 5;
  label: MoodLabel;
  tags: string[];
  /** Optional spoken comment recorded on the check-in (audio stays on the device in this prototype). */
  voiceNote?: VoiceNote;
}
export interface VoiceNote {
  /** Local audio URI (blob: on web, file:// on the phone). */
  uri: string;
  durationSec: number;
  /** Best-effort transcript (browser speech recognition or on-device Whisper). */
  transcript?: string;
}
export interface SleepData {
  bedtime: ISO;
  wakeTime: ISO;
  durationMin: number;
  quality: number;
  wakeUps: 'none' | '1-2' | '3+';
  source: 'archer_band' | 'manual';
  band?: { movementEvents: number; lightExposureLux: number; avgHr: number; respRate: number; noiseDb: number };
}
export interface RadiationData {
  value: number;
  unit: 'uSv' | 'mSv';
  doseUsv: number;
  source: 'personal' | 'area';
  badgeId?: string | null;
  particle: 'total' | 'neutron';
  illustrative: true;
}
export type Metric = 'blood_pressure' | 'bone_density' | 'muscle_mass' | 'strength' | 'aerobic';
export interface MeasurementData {
  metric: Metric;
  cadence: 'daily' | 'weekly';
  values: { systolic: number; diastolic: number; pulse: number } | { value: number; unit: string };
  deltaVsBaselinePct?: number | null;
}
export type InjuryPart = 'head' | 'neck' | 'back' | 'arm' | 'hand' | 'leg' | 'knee' | 'foot';
export interface InjuryData {
  bodyPart: InjuryPart;
  side: 'left' | 'right' | 'center';
  kind: 'bruise' | 'cut' | 'strain' | 'burn' | 'pain';
  severity: 'minor' | 'moderate' | 'severe';
  pain: number;
  description: string;
  photoUrl?: string | null;
  status: 'active' | 'healing' | 'resolved';
  flaggedToGround: boolean;
}
export interface MealData {
  name: string;
  items: string[];
  kcal: number;
  proteinG: number;
  carbsG: number;
  fatG: number;
  tasteRating: number;
}
export interface ExerciseData {
  modality: 'resistive' | 'aerobic';
  equipment: 'resistive_device' | 'treadmill' | 'cycle';
  durationMin: number;
  effort: number;
}
export interface MeditationData {
  session: string;
  durationMin: number;
  moodBefore: number;
  moodAfter: number;
}

export interface LogDataMap {
  mood: MoodData;
  sleep: SleepData;
  radiation: RadiationData;
  measurement: MeasurementData;
  injury: InjuryData;
  meal: MealData;
  exercise: ExerciseData;
  meditation: MeditationData;
}

export interface LogBase<T extends LogType = LogType> {
  id: string;
  astronautId: string;
  type: T;
  timestamp: ISO;
  missionDay: number;
  environmentId?: string | null;
  note?: string | null;
  coinsEarned: number;
  data: LogDataMap[T];
}
export type Log = { [K in LogType]: LogBase<K> }[LogType];
export type LogOf<T extends LogType> = LogBase<T>;

export interface DailySummary {
  astronautId: string;
  missionDay: number;
  logsDone: LogType[];
  logsDoneCount: number;
  logsTotal: number;
  overallScore: number;
  areas: Areas;
}

export interface EnvReading {
  id: string;
  environmentId: string;
  timestamp: ISO;
  temperatureC: number;
  pressureKpa: number;
  lightLux: number;
  noiseDb: number;
  radiationUsvH: number;
  crewPresent: number;
}

export type ChatMode = 'journal' | 'private';
export interface AiMessage {
  id: string;
  astronautId: string;
  author: 'astronaut' | 'orbi';
  text: string;
  timestamp: ISO;
  mode: ChatMode;
}
export interface JournalEntry {
  id: string;
  astronautId: string;
  timestamp: ISO;
  summary: string;
  moodLevel?: number;
  sourceMessageIds: string[];
}
export type AlertType = 'poor_sleep' | 'low_mood' | 'bone_loss' | 'fitness_drop' | 'menu_fatigue' | 'injury' | 'device_check';
export interface Alert {
  id: string;
  astronautId: string;
  type: AlertType;
  level: 'low' | 'medium' | 'high';
  text: string;
  evidence: string[];
  timestamp: ISO;
  sentToGround: boolean;
}
export interface AiChat {
  messages: AiMessage[];
  journal: JournalEntry[];
  alerts: Alert[];
}

export interface GroundMessage {
  id: string;
  astronautId: string;
  from: 'astronaut' | 'ground';
  text: string;
  urgent: boolean;
  sentAt: ISO;
  estimatedArrivalAt: ISO;
  status: 'sending' | 'in_transit' | 'delivered' | 'read';
  attachments: string[];
}

export interface ShopItem {
  id: string;
  category: ShopCategory;
  name: string;
  price: number;
  asset: string;
}

export interface CalendarEvent {
  id: string;
  astronautId: string;
  date: ISO;
  title: string;
  kind: 'test' | 'scan' | 'winddown' | 'call';
  linkedScreen: string;
}

export interface Db {
  currentAstronautId: string;
  mission: Mission;
  astronauts: Astronaut[];
  logs: Log[];
  daily_summaries: DailySummary[];
  environment_readings: EnvReading[];
  ai_chat: AiChat;
  ground_messages: GroundMessage[];
  shop: ShopItem[];
  calendar: CalendarEvent[];
  /** Backend only: who is signed in. Astronauts get their own data; the ground team gets the crew's. */
  role?: 'astronaut' | 'ground';
  /** Backend only: ranking numbers of the crew (an astronaut's snapshot has no logs of the others). */
  leaderboard?: { astronautId: string; logs: number; coins: number }[];
}
